CREATE DATABASE IF NOT EXISTS `gestion_rh` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `gestion_rh`;

CREATE TABLE `etablissements` (`idEtab` bigint(20) unsigned NOT NULL AUTO_INCREMENT,`nom` varchar(255) NOT NULL,`ville` varchar(255) NOT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`idEtab`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `specialites` (`idSpecialite` bigint(20) unsigned NOT NULL AUTO_INCREMENT,`nom_specialite` varchar(255) NOT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`idSpecialite`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `diplomes` (`idDiplome` bigint(20) unsigned NOT NULL AUTO_INCREMENT,`nom_diplome` varchar(255) NOT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`idDiplome`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `personnels` (`idPersonnel` bigint(20) unsigned NOT NULL AUTO_INCREMENT,`type_personnel` enum('formateur','administratif') NOT NULL,`statut` enum('permanent','vacataire') NOT NULL,`CIN` varchar(255) NOT NULL,`nom` varchar(255) NOT NULL,`prenom` varchar(255) NOT NULL,`date_naissance` date DEFAULT NULL,`situation_familiale` varchar(255) DEFAULT NULL,`adresse_actuelle` varchar(255) DEFAULT NULL,`lieu_naissance` varchar(255) DEFAULT NULL,`nombre_enfant` varchar(255) DEFAULT NULL,`telephone` varchar(255) DEFAULT NULL,`grade` varchar(255) DEFAULT NULL,`echelon` varchar(255) DEFAULT NULL,`fonction` varchar(255) DEFAULT NULL,`contact_nom` varchar(255) DEFAULT NULL,`contact_telephone` varchar(20) DEFAULT NULL,`idEtab` bigint(20) unsigned NOT NULL,`idSpecialite` bigint(20) unsigned DEFAULT NULL,`photo_url` varchar(255) DEFAULT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`idPersonnel`),UNIQUE KEY `personnels_cin_unique` (`CIN`),CONSTRAINT `personnels_idetab_foreign` FOREIGN KEY (`idEtab`) REFERENCES `etablissements` (`idEtab`) ON DELETE CASCADE,CONSTRAINT `personnels_idspecialite_foreign` FOREIGN KEY (`idSpecialite`) REFERENCES `specialites` (`idSpecialite`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `users` (`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,`username` varchar(255) NOT NULL,`email` varchar(255) NOT NULL,`password` varchar(255) NOT NULL,`Role` enum('directeurducomlex','gestionnairecfmr') NOT NULL,`idPersonnel` bigint(20) unsigned DEFAULT NULL,`active` tinyint(1) NOT NULL DEFAULT 1,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`),UNIQUE KEY `users_username_unique` (`username`),UNIQUE KEY `users_email_unique` (`email`),UNIQUE KEY `users_idpersonnel_unique` (`idPersonnel`),CONSTRAINT `users_idpersonnel_foreign` FOREIGN KEY (`idPersonnel`) REFERENCES `personnels` (`idPersonnel`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `absences` (`idAbsence` bigint(20) unsigned NOT NULL AUTO_INCREMENT,`date_absence` date NOT NULL,`motif` varchar(255) DEFAULT NULL,`idPersonnel` bigint(20) unsigned NOT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`idAbsence`),CONSTRAINT `absences_idpersonnel_foreign` FOREIGN KEY (`idPersonnel`) REFERENCES `personnels` (`idPersonnel`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `conges` (`idConge` bigint(20) unsigned NOT NULL AUTO_INCREMENT,`date_debut` date NOT NULL,`date_fin` date NOT NULL,`date_demande` date NOT NULL,`type_conge` varchar(255) NOT NULL,`statut` varchar(255) NOT NULL,`idPersonnel` bigint(20) unsigned NOT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`idConge`),CONSTRAINT `conges_idpersonnel_foreign` FOREIGN KEY (`idPersonnel`) REFERENCES `personnels` (`idPersonnel`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `obtenir` (`idPersonnel` bigint(20) unsigned NOT NULL,`idDiplome` bigint(20) unsigned NOT NULL,PRIMARY KEY (`idPersonnel`,`idDiplome`),CONSTRAINT `obtenir_iddiplome_foreign` FOREIGN KEY (`idDiplome`) REFERENCES `diplomes` (`idDiplome`) ON DELETE CASCADE,CONSTRAINT `obtenir_idpersonnel_foreign` FOREIGN KEY (`idPersonnel`) REFERENCES `personnels` (`idPersonnel`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `enseigner` (`idPersonnel` bigint(20) unsigned NOT NULL,`idSpecialite` bigint(20) unsigned NOT NULL,PRIMARY KEY (`idPersonnel`,`idSpecialite`),CONSTRAINT `enseigner_idpersonnel_foreign` FOREIGN KEY (`idPersonnel`) REFERENCES `personnels` (`idPersonnel`) ON DELETE CASCADE,CONSTRAINT `enseigner_idspecialite_foreign` FOREIGN KEY (`idSpecialite`) REFERENCES `specialites` (`idSpecialite`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `personal_access_tokens` (`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,`tokenable_type` varchar(255) NOT NULL,`tokenable_id` bigint(20) unsigned NOT NULL,`name` text NOT NULL,`token` varchar(64) NOT NULL,`abilities` text DEFAULT NULL,`last_used_at` timestamp NULL DEFAULT NULL,`expires_at` timestamp NULL DEFAULT NULL,`created_at` timestamp NULL DEFAULT NULL,`updated_at` timestamp NULL DEFAULT NULL,PRIMARY KEY (`id`),UNIQUE KEY `personal_access_tokens_token_unique` (`token`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
